rows=json.loads((Path(__file__).resolve().parents[1]/'data/ejemplos.json').read_text())
layout=html.Div([html.H1('Seis recortes originales para probar CICO'),html.P('Dos por clase, RGB 128 × 128, con bytes y píxeles verificados contra el manifiesto. Clase real significa referencia del dataset, no nueva revisión clínica. Proceden de validación: no son un test independiente.'),html.A('Abrir el formulario de predicción',href='/prediccion',className='button'),html.Div([html.Section([html.H2('Caso '+r['caso']+' · '+r['clase_referencia']),html.Img(src='data:image/png;base64,'+(Path(__file__).resolve().parents[1]/r['png_file']).read_text(),alt=r['clase_referencia'],style={'width':'256px','imageRendering':'pixelated','maxWidth':'100%'}),html.P(r['explicacion']),html.P('CICO 6101: '+r['prediccion_cico']+' · '+('coincide' if r['coincide'] else 'discrepa')+' con la referencia. Predicción CPU local con el mismo ONNX desplegado.'),html.A('Descargar PNG original',href='/ejemplo-png/'+r['caso'],className='button'),html.P('Caso '+r['caso']+' de la galería E2. Selección ilustrativa previa a inferencia CICO; no estima precisión.')],className='panel') for r in rows],className='grid'),html.A('Explicación y localización del núcleo en el libro',href='/libro/20_ejemplos_prediccion.html')])
